// Parse YC HTML into job objects
const items = $input.all();
const jobs = [];

for (const item of items) {
  const html = item.json.data || item.json.body || '';
  const source = item.json.source || 'YC Work at Startup';

  // Extract job cards via regex (adjust selectors if YC changes markup)
  const titleMatches = html.matchAll(/class="[^"]*job-title[^"]*"[^>]*>([^<]+)</gi);
  const companyMatches = html.matchAll(/class="[^"]*company-name[^"]*"[^>]*>([^<]+)</gi);
  const urlMatches = html.matchAll(/href="(\/jobs\/[^"]+)"/gi);

  const titles = [...titleMatches].map(m => m[1].trim());
  const companies = [...companyMatches].map(m => m[1].trim());
  const urls = [...new Set([...urlMatches].map(m => `https://www.workatastartup.com${m[1]}`))]; 

  for (let i = 0; i < Math.min(titles.length, 20); i++) {
    jobs.push({
      json: {
        job_title: titles[i] || '',
        company: companies[i] || '',
        job_url: urls[i] || '',
        source: source,
        location_text: 'Remote',
        salary: '',
        description: '',
        posted_date: new Date().toISOString(),
        tags: ''
      }
    });
  }
}

return jobs.length > 0 ? jobs : [{ json: { job_title: '', company: '', job_url: '', source: 'YC', location_text: '', salary: '', description: '', posted_date: new Date().toISOString(), tags: '', _empty: true } }];

const items = $input.all();
const normalized = [];
const seenUrls = new Set();

const KEYWORDS = [
  'async remote','asynchronous remote','worldwide remote','global remote',
  'work from anywhere','remote data analyst','remote data scientist',
  'remote ai marketing','remote marketing analyst','remote growth analyst',
  'remote bi analyst','remote automation specialist','remote ai workflow',
  'data analyst','data scientist','business intelligence','bi analyst',
  'marketing analyst','growth analyst','ai marketing','ai automation',
  'performance marketing','martech','analytics'
];

for (const item of items) {
  const d = item.json;

  // Skip empty sentinel rows
  if (d._empty) continue;

  // Determine source-specific field mappings
  let job_title = d.position || d.title || d.job_title || d.name || '';
  let company   = d.company_name || d.company || d.organization || d.employer || '';
  let job_url   = d.url || d.apply_url || d.link || d.job_url || d.guid || '';
  let source    = d.source || 'unknown';
  let location  = d.candidate_required_location || d.location || d.job_location || d.region || '';
  let salary    = d.salary || d.compensation || d.salary_range || '';
  let desc      = d.description || d.job_description || d.content || d.summary || '';
  let posted    = d.date || d.pubDate || d.created_at || d.published || new Date().toISOString();
  let tags      = Array.isArray(d.tags) ? d.tags.join(', ') : (d.tags || d.categories || '');

  // Clean HTML from description
  desc = desc.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 3000);

  job_title = job_title.toString().trim();
  company   = company.toString().trim();
  job_url   = job_url.toString().trim();

  if (!job_title || !job_url) continue;

  // Source tag for Remote OK (first item is metadata)
  if (d.legal) continue; // Remote OK metadata row

  // Deduplicate by URL at normalize stage
  if (job_url && seenUrls.has(job_url)) continue;
  if (job_url) seenUrls.add(job_url);

  // Keyword relevance pre-filter: must match at least one keyword in title or desc
  const searchText = (job_title + ' ' + desc + ' ' + tags).toLowerCase();
  const isRelevant = KEYWORDS.some(kw => searchText.includes(kw));
  if (!isRelevant) continue;

  const job_id = job_url || `${company}||${job_title}`.toLowerCase().replace(/\s+/g, '-');

  normalized.push({
    json: {
      job_id,
      job_title,
      company,
      job_url,
      source,
      location_text: location.toString().trim(),
      salary: salary.toString().trim(),
      description: desc,
      posted_date: posted.toString().substring(0, 10),
      tags: tags.toString().trim(),
      date_found: new Date().toISOString().split('T')[0]
    }
  });
}

return normalized.length > 0 ? normalized : [];

// Get new jobs from normalize node
const newJobs = $('Normalize Job Data').all();

// Get existing records from Google Sheets
const existingRows = $('Get Existing Job URLs').all();

const existingUrls = new Set();
const existingKeys = new Set();

for (const row of existingRows) {
  if (row.json.job_url) existingUrls.add(row.json.job_url.trim());
  if (row.json.job_id) existingUrls.add(row.json.job_id.trim());
  if (row.json.company && row.json.job_title) {
    existingKeys.add(`${row.json.company}||${row.json.job_title}`.toLowerCase());
  }
}

const unique = [];
const seenUrls = new Set();
const seenKeys = new Set();

for (const item of newJobs) {
  const job = item.json;
  const url = (job.job_url || '').trim();
  const key = `${job.company}||${job.job_title}`.toLowerCase();

  if (url && (existingUrls.has(url) || seenUrls.has(url))) continue;
  if (!url && (existingKeys.has(key) || seenKeys.has(key))) continue;

  if (url) seenUrls.add(url);
  seenKeys.add(key);
  unique.push(item);
}

return unique;

const items = $input.all();
const results = [];

const REJECT_PATTERNS = [
  { re: /\bus[- ]only\b/i,                  reason: 'US only' },
  { re: /\bcanada[- ]only\b/i,              reason: 'Canada only' },
  { re: /\buk[- ]only\b/i,                  reason: 'UK only' },
  { re: /\beu[- ]only\b/i,                  reason: 'EU only' },
  { re: /\beurope[- ]only\b/i,              reason: 'Europe only' },
  { re: /\baustralia[- ]only\b/i,            reason: 'Australia only' },
  { re: /must be based in/i,                reason: 'must be based in' },
  { re: /must live in/i,                    reason: 'must live in' },
  { re: /must be authorized to work in/i,   reason: 'work authorization required' },
  { re: /authorized to work in the (us|uk|eu|canada|australia)/i, reason: 'work authorization required' },
  { re: /local work permit required/i,      reason: 'local work permit required' },
  { re: /\bhybrid\b/i,                      reason: 'hybrid' },
  { re: /\bon[- ]?site\b/i,                 reason: 'onsite' },
  { re: /office required/i,                 reason: 'office required' },
  { re: /remote within [a-z ]+ only/i,      reason: 'country-restricted remote' },
  { re: /fixed (us|est|pst|cst|cet) hours/i, reason: 'fixed timezone hours' },
  { re: /must (reside|relocate) in/i,       reason: 'relocation required' },
  { re: /citizens? or (permanent )?residents? only/i, reason: 'citizenship required' }
];

const STRONG_PASS_PATTERNS = [
  /worldwide remote/i,
  /global remote/i,
  /work from anywhere/i,
  /\banywhere\b/i,
  /apac remote/i,
  /international contractors? accepted/i,
  /\bb2b contractor\b/i,
  /hires? via deel/i,
  /hires? via remote\.com/i,
  /hires? via oyster/i,
  /\beor[ -]supported\b/i,
  /distributed team/i
];

for (const item of items) {
  const job = item.json;
  const fullText = [
    job.location_text || '',
    job.description || '',
    job.job_title || '',
    job.tags || ''
  ].join(' ');

  let hard_filter_result = 'pass';
  let hard_filter_reason = '';

  // Strong pass: if any strong pass pattern matches, skip reject checks
  const strongPass = STRONG_PASS_PATTERNS.some(p => p.test(fullText));

  if (!strongPass) {
    for (const { re, reason } of REJECT_PATTERNS) {
      if (re.test(fullText)) {
        hard_filter_result = 'reject';
        hard_filter_reason = reason;
        break;
      }
    }
  }

  results.push({
    json: {
      ...job,
      hard_filter_result,
      hard_filter_reason,
      strong_pass: strongPass
    }
  });
}

return results;

