const items = $input.all();
const results = [];

for (const item of items) {
  // The HTTP Request node returns the AI response; the original job is in the paired input
  // We need to merge AI response with original job data
  const aiRaw = item.json;

  // Extract text from Claude response
  let aiText = '';
  try {
    aiText = aiRaw.content?.[0]?.text || aiRaw.choices?.[0]?.message?.content || '';
  } catch(e) { aiText = ''; }

  // Parse JSON from AI response
  let ai = {
    taiwan_eligible: 'unclear',
    reason: 'AI check failed',
    location_risk: 'medium',
    timezone_risk: 'medium',
    contractor_possible: 'unclear',
    decision: 'manual_check'
  };

  try {
    const match = aiText.match(/\{[\s\S]*\}/);
    if (match) ai = { ...ai, ...JSON.parse(match[0]) };
  } catch(e) {}

  // Retrieve original job — the AI Check node receives one item at a time
  // so $('Save to Raw Jobs Sheet').item refers to the same execution item
  // We pass original job fields through via the input context
  const job = item.json._originalJob || {};

  // --- SCORING ---
  let score = 0;
  let async_level = 'none';
  let role_category = 'other';

  const desc   = ((job.description || '') + ' ' + (job.location_text || '') + ' ' + (job.tags || '')).toLowerCase();
  const title  = (job.job_title || '').toLowerCase();
  const salary = (job.salary || '').toString();

  // Taiwan eligibility: 0-40 pts
  if (ai.taiwan_eligible === 'yes' || ai.decision === 'keep') {
    if (/worldwide|work from anywhere|global remote|anywhere|apac/.test(desc)) {
      score += 40;
    } else if (/contractor|deel|remote\.com|oyster|eor|distributed/.test(desc)) {
      score += 30;
    } else {
      score += 20;
    }
  } else if (ai.taiwan_eligible === 'unclear' || ai.decision === 'manual_check') {
    score += 20;
  }
  // 0 pts for 'no'

  // Async fit: 0-25 pts
  if (/\basync\b|\basynchronous\b/.test(desc)) {
    score += 25; async_level = 'high';
  } else if (/flexible hours|flexible schedule|set your own hours/.test(desc)) {
    score += 20; async_level = 'medium';
  } else if (/distributed team|remote.?first|low meeting|work across time zones/.test(desc)) {
    score += 15; async_level = 'medium';
  } else if (/remote first|overlap/.test(desc)) {
    score += 10; async_level = 'low';
  }

  // Role fit: 0-25 pts
  const dataRoleRe    = /data analyst|data scientist|bi analyst|business intelligence|marketing analyst|growth analyst|ai marketing|ai automation|automation specialist|performance marketing|martech|analytics engineer|marketing data|growth hacker/i;
  const adjacentRoleRe = /analyst|marketing|growth|seo|ppc|digital marketing|campaign|automation|machine learning|ai specialist/i;
  if (dataRoleRe.test(title)) {
    score += 25; role_category = 'data_ai_marketing';
  } else if (adjacentRoleRe.test(title)) {
    score += 15; role_category = 'adjacent';
  }

  // Salary fit: 0-25 pts
  const salaryNums = salary.match(/[\d,]+/g);
  let salaryMonthly = 0;
  if (salaryNums) {
    const nums = salaryNums.map(n => parseInt(n.replace(/,/g, '')));
    salaryMonthly = Math.max(...nums);
    // Convert annual to monthly if large
    if (salaryMonthly > 50000) salaryMonthly = Math.round(salaryMonthly / 12);
  }
  if (salaryMonthly >= 5000) { score += 25; }
  else if (salaryMonthly >= 3000) { score += 15; }
  else if (salary) { score += 10; }

  // Async reject penalty
  const asyncRejectRe = /strict 9.to.5|fixed (us|est|pst|cst|cet|gmt) hours|daily live calls required|must overlap full business day/i;
  const passes_async = !asyncRejectRe.test(desc);
  if (!passes_async) score = Math.max(0, score - 20);

  // Why good fit summary
  const fits = [];
  if (ai.taiwan_eligible === 'yes') fits.push('Taiwan-eligible');
  if (async_level === 'high') fits.push('fully async');
  if (async_level === 'medium') fits.push('flexible hours');
  if (role_category === 'data_ai_marketing') fits.push('strong role match');
  if (salaryMonthly >= 5000) fits.push(`good salary (~$${salaryMonthly.toLocaleString()}/mo)`);
  else if (salaryMonthly >= 3000) fits.push(`decent salary (~$${salaryMonthly.toLocaleString()}/mo)`);
  const why_good_fit = fits.join(', ');

  results.push({
    json: {
      ...job,
      taiwan_eligible: ai.taiwan_eligible,
      taiwan_reason: ai.reason,
      location_risk: ai.location_risk,
      timezone_risk: ai.timezone_risk,
      contractor_possible: ai.contractor_possible,
      ai_decision: ai.decision,
      async_level,
      role_category,
      score,
      passes_async,
      why_good_fit,
      salary_monthly_est: salaryMonthly,
      application_status: 'new',
      notes: ''
    }
  });
}

return results;

// Pair original job data (from Save to Raw Jobs Sheet) with AI response (from AI Taiwan Eligibility Check)
// In n8n, when items flow through multiple nodes, we need to re-attach original job data
const aiResponses = $('AI Taiwan Eligibility Check').all();
const originalJobs = $('Save to Raw Jobs Sheet').all();

const results = [];

for (let i = 0; i < aiResponses.length; i++) {
  const aiItem = aiResponses[i];
  const jobItem = originalJobs[i] || { json: {} };

  let aiText = '';
