const allItems = $input.all();

// Separate filtered vs rejected
const filtered = allItems.filter(i => i.json.score !== undefined && i.json.score >= 70);
const rejected  = allItems.filter(i => !i.json.score || i.json.score < 70);

// Sort filtered by score desc
filtered.sort((a, b) => (b.json.score || 0) - (a.json.score || 0));

// Rejection reason counts
let rejectedUS = 0, rejectedEU = 0, rejectedHybrid = 0, rejectedTZ = 0, rejectedScore = 0;
for (const r of rejected) {
  const reason = (r.json.reason || '').toLowerCase();
  if (/us only|united states/.test(reason))   rejectedUS++;
  else if (/eu only|europe/.test(reason))      rejectedEU++;
  else if (/hybrid|onsite/.test(reason))       rejectedHybrid++;
  else if (/timezone|fixed.*hours/.test(reason)) rejectedTZ++;
  else                                          rejectedScore++;
}

// Top jobs section
const top = filtered.slice(0, 10);
const manualCheck = filtered.filter(j => j.json.taiwan_eligible === 'unclear');

const today = new Date().toLocaleDateString('en-US', { weekday:'long', year:'numeric', month:'long', day:'numeric' });

let msg = `🇹🇼 Daily Taiwan Eligible Async Remote Jobs\n`;
msg += `📅 ${today}\n`;
msg += `✅ ${filtered.length} eligible jobs found today | ❌ ${rejected.length} rejected\n`;
msg += `${'─'.repeat(35)}\n\n`;

if (top.length === 0) {
  msg += `No eligible jobs found today. Try adjusting keywords or check back tomorrow.\n`;
} else {
  msg += `🌟 TOP JOBS TODAY:\n\n`;
  top.forEach((item, i) => {
    const j = item.json;
    msg += `${i + 1}. ${j.job_title}\n`;
    msg += `   Company: ${j.company}\n`;
    msg += `   Score: ${j.score}/100\n`;
    msg += `   Taiwan Eligible: ${j.taiwan_eligible}\n`;
    msg += `   Reason: ${j.taiwan_reason || 'N/A'}\n`;
    msg += `   Async Level: ${j.async_level}\n`;
    msg += `   Timezone Risk: ${j.timezone_risk}\n`;
    msg += `   Salary: ${j.salary || 'Not listed'}\n`;
    msg += `   Why it fits Jerry: ${j.why_good_fit}\n`;
    msg += `   Apply: ${j.job_url}\n\n`;
  });
}

if (manualCheck.length > 0) {
  msg += `\n⚠️ MANUAL CHECK (unclear Taiwan eligibility):\n`;
  manualCheck.slice(0, 5).forEach(item => {
    const j = item.json;
    msg += `• ${j.job_title} @ ${j.company} (Score: ${j.score}) — ${j.job_url}\n`;
  });
}

msg += `\n📊 REJECTED SUMMARY:\n`;
msg += `• US only: ${rejectedUS}\n`;
msg += `• EU only: ${rejectedEU}\n`;
msg += `• Hybrid/Onsite: ${rejectedHybrid}\n`;
msg += `• Timezone risk: ${rejectedTZ}\n`;
msg += `• Score too low: ${rejectedScore}\n`;

// Trim to Telegram limit (4096 chars)
if (msg.length > 4000) {
  msg = msg.substring(0, 3950) + '\n\n[... truncated, check Google Sheets for full list]';
}

return [{ json: { message: msg, jobs_found: filtered.length, jobs_rejected: rejected.length } }];
